if(dataSet){
    var count = dataSet.getRowCount();
    if(count>0){
        var dangerId = "";
        for(var i=0;i<count;i++){
            var rowSet = dataSet.getRowSet(i);
            var code = rowSet.getString("DANGER_ID","");
            if(i==count-1){
                dangerId+=code;
            }else{
                dangerId+=code+",";
            }

        }
        if(dangerId!=""){
            var PO = new JParamObject();
            PO.setValueByParamName("dangerId",dangerId);
            WebService2.SVR("DangerDeleteService",PO,null);
        }
    }
}

