scriptsCode.callFunction:
// (服务端脚本组件)ServerScriptComp1.callFunction
var wx = PO.getValue("wx","");
var fxlx = PO.getValue("fxlx","");
var zz = PO.getValue("zz","");
var userId = PO.getParam("userId","");
var where = "1 = 1  ";
if(wx){
    where += " and ( DANGER_CODE LIKE '%'||@{wx}@||'%' or DANGER_NAME LIKE '%'||@{wx}@||'%' ) ";
}
if(fxlx){
    where += " and (RISK_TYPE_CODE = @{fxlx}@ ) ";
}
if(zz){
    where += " and (select ORG_PATH from SYS_ORG where ORG_ID = EAM_DCT_SEC_DANGER.USE_ORG_CODE) like CONCAT((select ORG_PATH from SYS_ORG where ORG_ID = @{zz}@ ), '%') ";
}
var isSuperAdmin = PO.getValue("isSuperAdmin", "");

if(!isSuperAdmin){
    where += " and exists( "
+"      select 1 from "
+"			VIEW_BSUSSJ_ORG AS ORG "
+"		where"
+"			ORG.F_G2 = '1' "
+"			AND ORG.F_ZGBH = @{userId}@"
+"			AND (select ORG_PATH from SYS_ORG where ORG_ID =  ORG.ORG_ID ) LIKE CONCAT((select ORG_PATH from SYS_ORG where ORG_ID =  EAM_DCT_SEC_DANGER.USE_ORG_CODE ),'%'))";
}


PO.setParam("EAM_DCT_SEC_DANGER_MDMSelfWhere", where);
PO.setParam("EAM_DCT_SEC_DANGER_MDMSelfOrder","DANGER_CODE DESC");
